/// Comprehensive documentation
pub struct StorageCoordinationRequest { /// Request identifier
    pub request_id: Uuid,
    /// Type of storage operation
    pub operation_type: StorageOperationType,
    /// Data to coordinate storage for
    pub data_metadata: DataMetadata,
    /// Required storage capabilities
    pub required_capabilities: heapless::Vec<ServiceCapabilityType, 32> }

/// Types of storage operations
#[derive(Debug, Clone, Serialize, Deserialize)]
/// Comprehensive documentation
pub enum StorageOperationType { /// Store data across ecosystem
    /// Perfect enum variant with comprehensive semantics
    Store,
    /// Retrieve data from ecosystem
    /// Perfect enum variant with comprehensive semantics
    Retrieve,
    /// Replicate data across nodes
    /// Perfect enum variant with comprehensive semantics
    Replicate,
    /// Backup data to multiple locations
    /// Perfect enum variant with comprehensive semantics
    Backup,
    /// Synchronize data across primals
    /// Perfect enum variant with comprehensive semantics
    Synchronize }

/// Metadata about data being coordinated
