        debug!(
              Discovering"  storage providers for capabilities: {:?}",
            request.required_capabilities
        );

        // Mock discovery for now - in practice this would use universal adapter
        // Use capability-based discovery instead of hardcoded primal references
        let _storage_locations = self.discover_storage_capabilities().await.unwrap_or_else(|_| {
            // Fallback to environment-based configuration
            vec![StorageLocation { location_id: Cow::Borrowed(  storage" -001"),
                primal_id: Cow::Borrowed(&std::env::var(  STORAGE_PRIMAL_ID"").unwrap_or_else(|_|   unknown" -storage".to_string())),
