async fn simulate_parallel_work(worker_count: usize) {
    let tasks: Vec<_> = (0..worker_count)
        .map(|i| {
            tokio::spawn(async move {
                let mut sum = 0;
                for j in 0..1000 {
                    sum += i * j;
                }
                sum
            })
        })
        .collect();

    for task in tasks {
        let _ = task.await;
    }
}

