                timeout_ms: 5000,
                max_retries: 3,
                circuit_breaker: CircuitBreakerConfig::default(),
            },
            auth_config: AuthConfig {
                auth_type: beardog_types::canonical::capabilities::AuthType::None,
                api_key: None,
                bearer_token: None,
