/// **ERROR ANALYTICS** - Error analytics and metrics
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ErrorAnalytics {
    /// Error severity level
    pub severity: ErrorSeverity,

    /// Error category
    pub category: String,

    /// Error subcategory
