    #[test]
    fn test_rule_execution() {
        let condition = RuleCondition::field_equals("event_type", "login");
        let rule = DetectionRule::new(
            "rule-1",
            "Login Detection",
            "Detects login events",
            ThreatRuleType::Signature,
            ThreatSeverity::Medium,
