        for (i, byte) in key.iter_mut().enumerate() {
            let mutation_intensity = (fitness_score * 255.0) as u8;
            let genetic_factor = (i as u64 * 0x9E3779B97F4A7C15) >> 56;
            *byte = byte.wrapping_add(mutation_intensity ^ genetic_factor as u8);
