    fn apply_simd_key_transformation(&self, key: &mut [u8]) -> Result<(), BearDogError> {
        const SIMD_CHUNK_SIZE: usize = 32; // AVX2 vector size
        for chunk in key.chunks_mut(SIMD_CHUNK_SIZE) {
