        source_metadata.insert("method".to_string(), format!("{:?}", method));
        source_metadata.insert(
            "collection_timestamp".to_string(),
            chrono::Utc::now().timestamp().to_string(),
        );
        source_metadata.insert(
            "anti_replay_nonce".to_string(),
