        match self.get_human_entropy_capabilities() {
            Ok(caps) => caps.supports_ephemeral_seeds,
            Err(_) => false,
        }
    }

/// Supports Attestation operation.
    pub fn supports_attestation(&self) -> bool {
        match self.get_hardware_attestation() {
            Ok(Some(_)) => true,
            Ok(None) => false,
            Err(_) => false,
        }
    }

