        for path in library_paths {
            if Path::new({}", path);
                let hsm = DiscoveredHsm {
                    hsm_id: format!("pkcs11-{}", path), // path is already a String
                    name: format!("PKCS#11 HSM ({})", self.detect_vendor_from_path(crate::universal_hsm_discovery::HsmType::Hardware,
