impl SystemDomainConfig {
    /// Load system configuration from environment variables
    pub fn from_env() -> Result<Self, BearDogError> {
        let mut config = Self::default();

        // Load environment type
        if let Ok(env_type) = std::env::var("BEARDOG_ENVIRONMENT") {
            config.environment.environment_type = env_type;
        }

        // Load logging configuration
        if let Ok(log_level) = std::env::var("BEARDOG_LOG_LEVEL") {
            config.logging.level = match log_level.to_lowercase().as_str() {
                "trace" => LogLevel::Trace,
                "debug" => LogLevel::Debug,
                "info" => LogLevel::Info,
                "warn" | "warning" => LogLevel::Warn,
                "error" => LogLevel::Error,
                _ => LogLevel::Info, // Default to Info if invalid
            };
        }

        if let Ok(log_format) = std::env::var("BEARDOG_LOG_FORMAT") {
            config.logging.format = match log_format.to_lowercase().as_str() {
                "json" => LogFormat::Json,
                "text" => LogFormat::Text,
                "structured" => LogFormat::Structured,
                "compact" => LogFormat::Compact,
                _ => LogFormat::Json, // Default to JSON if invalid
            };
        }

        // Load threading configuration
        if let Ok(worker_threads) = std::env::var("BEARDOG_WORKER_THREADS") {
            config.threading.worker_threads = worker_threads
                .parse()
                .map_err(|_| BearDogError::validation("Invalid BEARDOG_WORKER_THREADS value"))?;
        }

        // Load resource limits
        if let Ok(max_connections) = std::env::var("BEARDOG_MAX_CONNECTIONS") {
            config.resources.max_connections = max_connections
                .parse()
                .map_err(|_| BearDogError::validation("Invalid BEARDOG_MAX_CONNECTIONS value"))?;
        }

        Ok(config)
    }

    /// Validate system configuration
    pub fn validate(&self) -> Result<(), BearDogError> {
        // Validate threading configuration
        if self.threading.worker_threads == 0 {
            return Err(BearDogError::validation(
                "Worker threads must be greater than 0",
            ));
        }

        if self.threading.blocking_threads == 0 {
            return Err(BearDogError::validation(
                "Blocking threads must be greater than 0",
            ));
        }

        // Validate resource limits
        if self.resources.max_connections == 0 {
            return Err(BearDogError::validation(
                "Max connections must be greater than 0",
            ));
        }

        // Validate logging configuration (delegates to LoggingConfig::validate)
        self.logging.validate()?;

        Ok(())
    }
}

//! Canonical Testing Configuration Module
//!
//! This module consolidates ALL test configuration types from scattered locations
//! across the codebase into a single canonical source of truth.
//!
//! ## 🎯 Consolidation Achievement
//!
//! **Previously Scattered Locations** (Now Unified):
//! - `tests/common/zero_cost_harness.rs::TestConfig`
//! - `tests/api/comprehensive_tests.rs::ApiTestConfig`
//! - `tests/production/deployment_validation.rs::ProductionDeploymentConfig`
//! - `tests/world_class_testing_framework.rs::TestingConfiguration`
//! - `tests/clone_optimization_benchmark.rs::BenchmarkConfig`
//! - `crates/beardog-integration-tests/src/unified_architecture_tests.rs::TestConfig`
//!
//! **Migration Guide**:
//! ```rust
//! // Old (scattered)
//! use crate::TestConfig;
//!
//! // New (canonical)
//! use beardog_types::canonical::config::domains::testing::{
//!     CanonicalTestConfig,
//!     CanonicalApiTestConfig,
//!     CanonicalBenchmarkConfig,
//! };
//! ```

use beardog_errors::BearDogResult;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::time::Duration;

// ============================================================================
// CANONICAL TEST CONFIGURATIONS
// ============================================================================

/// **Canonical Test Configuration** - General test configuration
///
/// Consolidates test settings for unit, integration, and functional testing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CanonicalTestConfig {
    /// Test environment name
    pub environment: String,

    /// Enable verbose output
    pub verbose: bool,

    /// Enable parallel test execution
    pub parallel_execution: bool,

    /// Maximum number of parallel test threads
    pub max_threads: usize,

    /// Test timeout in seconds
    pub timeout_seconds: u64,

    /// Enable test coverage collection
    pub collect_coverage: bool,

    /// Test data directory
    pub test_data_dir: PathBuf,

    /// Enable property-based testing
    pub property_testing_enabled: bool,

    /// Number of property test iterations
    pub property_test_iterations: u32,

    /// Enable fuzzing tests
    pub fuzzing_enabled: bool,

    /// Random seed for reproducible tests
    pub random_seed: Option<u64>,
}

impl Default for CanonicalTestConfig {
    fn default() -> Self {
        Self {
            environment: "test".to_string(),
            verbose: false,
            parallel_execution: true,
            max_threads: std::thread::available_parallelism()
                .map(std::num::NonZeroUsize::get)
                .unwrap_or(4),
            timeout_seconds: 300,
            collect_coverage: false,
            test_data_dir: PathBuf::from("test-data"),
            property_testing_enabled: true,
            property_test_iterations: 100,
            fuzzing_enabled: false,
            random_seed: None,
        }
    }
}

impl CanonicalTestConfig {
    /// Create a new test configuration with defaults
    pub fn new() -> Self {
        Self::default()
    }

    /// Create configuration for fast tests
    pub fn fast() -> Self {
        let default_threads = std::thread::available_parallelism()
            .map(std::num::NonZeroUsize::get)
            .unwrap_or(4);
        Self {
            parallel_execution: true,
            max_threads: default_threads * 2,
            timeout_seconds: 30,
            property_test_iterations: 10,
            ..Default::default()
        }
    }

    /// Create configuration for thorough testing
    pub fn thorough() -> Self {
        Self {
            parallel_execution: true,
            collect_coverage: true,
            property_testing_enabled: true,
            property_test_iterations: 1000,
            fuzzing_enabled: true,
            timeout_seconds: 600,
            ..Default::default()
        }
    }

    /// Validate the configuration
    pub fn validate(&self) -> BearDogResult<()> {
        if self.max_threads == 0 {
            return Err(beardog_errors::BearDogError::validation(
                "max_threads must be greater than 0",
            ));
        }
        if self.timeout_seconds == 0 {
            return Err(beardog_errors::BearDogError::validation(
                "timeout_seconds must be greater than 0",
            ));
        }
        Ok(())
    }
}

