    Custom(String),
}

/// **Provider Capability Description** - Struct-based capability for dynamic configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProviderCapability {
    /// Capability type
    pub capability_type: ProviderCapabilityType,
    /// Capability name
    pub name: String,
    /// Capability version
    pub version: String,
    /// Capability description
    pub description: String,
    /// Required configuration parameters
    pub required_config: Vec<String>,
    /// Optional configuration parameters
    pub optional_config: Vec<String>,
    /// Whether this capability is enabled
    pub enabled: bool,
    /// Capability-specific metadata
    pub metadata: HashMap<String, String>,
}

impl ProviderCapability {
    /// Create a new capability with the given type and basic information
    pub fn new(
        capability_type: ProviderCapabilityType,
        name: impl Into<String>,
        version: impl Into<String>,
        description: impl Into<String>,
    ) -> Self {
        Self {
            capability_type,
            name: name.into(),
            version: version.into(),
            description: description.into(),
            required_config: Vec::new(),
            optional_config: Vec::new(),
            enabled: true,
            metadata: HashMap::new(),
        }
    }

    /// Create a key generation capability
    pub fn key_generation() -> Self {
        Self::new(
            ProviderCapabilityType::KeyGeneration,
            "Key Generation",
            "1.0.0",
            "Generate cryptographic keys",
        )
    }

    /// Create an encryption capability
    pub fn encryption() -> Self {
        Self::new(
            ProviderCapabilityType::Encryption,
            "Encryption",
            "1.0.0",
            "Encrypt and decrypt data",
        )
    }

    /// Create a signing capability
    pub fn signing() -> Self {
        Self::new(
            ProviderCapabilityType::Signing,
            "Digital Signing",
            "1.0.0",
            "Create and verify digital signatures",
        )
    }

    /// Create a custom capability
    pub fn custom(name: impl Into<String>, description: impl Into<String>) -> Self {
        let name_str = name.into();
        Self::new(
            ProviderCapabilityType::Custom(name_str.clone()),
            name_str,
            "1.0.0",
            description,
        )
    }
}

/// **Capability Set** - Collection of capabilities for a provider
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CapabilitySet {
    /// Set of capabilities
    pub capabilities: Vec<ProviderCapability>,
    /// Capability set version
    pub version: String,
    /// Capability set metadata
    pub metadata: HashMap<String, String>,
}

impl CapabilitySet {
    /// Create a new empty capability set
    pub fn new() -> Self {
        Self {
            capabilities: Vec::new(),
            version: "1.0.0".to_string(),
            metadata: HashMap::new(),
        }
    }

    /// Add a capability to the set
    pub fn add_capability(&mut self, capability: ProviderCapability) {
        self.capabilities.push(capability);
    }

    /// Check if the set contains a specific capability type
    pub fn has_capability(&self, capability_type: &ProviderCapabilityType) -> bool {
        self.capabilities
            .iter()
            .any(|cap| &cap.capability_type == capability_type && cap.enabled)
    }

    /// Get all capabilities of a specific type
    pub fn get_capabilities_by_type(
        &self,
        capability_type: &ProviderCapabilityType,
    ) -> Vec<&ProviderCapability> {
        self.capabilities
            .iter()
            .filter(|cap| &cap.capability_type == capability_type)
            .collect()
    }

    /// Create a capability set for HSM providers
    pub fn hsm_capabilities() -> Self {
        let mut set = Self::new();
        set.add_capability(ProviderCapability::key_generation());
        set.add_capability(ProviderCapability::encryption());
        set.add_capability(ProviderCapability::signing());
        set.metadata.insert("provider_type".to_string(), "hsm".to_string());
        set
    }

    /// Create a capability set for security providers
    pub fn security_capabilities() -> Self {
        let mut set = Self::new();
        set.add_capability(ProviderCapability::authentication());
        set.add_capability(ProviderCapability::authorization());
        set.add_capability(ProviderCapability::encryption());
        set.metadata.insert("provider_type".to_string(), "security".to_string());
        set
    }
}

impl Default for CapabilitySet {
    fn default() -> Self {
        Self::new()
    }
}

impl ProviderCapability {
    /// Create an authentication capability
    pub fn authentication() -> Self {
        Self::new(
            ProviderCapabilityType::Authentication,
            "Authentication",
            "1.0.0",
            "User and service authentication",
        )
    }

    /// Create an authorization capability
    pub fn authorization() -> Self {
        Self::new(
            ProviderCapabilityType::Authorization,
            "Authorization",
            "1.0.0",
            "Access control and authorization",
        )
    }
}

//! # Consolidated Provider Trait System - CANONICAL LOCATION
//!
//! This module provides the **single source of truth** for all provider traits across
//! the `BearDog` ecosystem. It consolidates and replaces all scattered provider trait
//! definitions with a unified, hierarchical trait system.
//!
//! ## 🎯 **Consolidation Strategy**
//!
//! This module unifies and replaces:
//! - `beardog-traits/src/unified/providers.rs` - Original unified provider traits
//! - `beardog-traits/src/unified/providers_consolidated.rs` - Consolidated provider traits
//! - `beardog-traits/src/canonical/*Provider` - Legacy canonical provider traits
//! - Scattered provider trait definitions across all crates
//!
//! ## 🏗️ **Architecture Principles**
//!
//! - **Single Source of Truth**: All provider traits defined in one location
//! - **Hierarchical Design**: Clear inheritance from base to specialized traits
//! - **Native Async**: All operations use native async/await (no `async_trait`)
//! - **Type Safety**: Strong typing with associated types and comprehensive error handling
//! - **Zero Fragmentation**: No duplicate trait definitions anywhere in the ecosystem
//! - **Performance Optimized**: Zero-cost abstractions with efficient implementations
//!
//! ## 📊 **Provider Hierarchy**
//!
//! ```text
//! ConsolidatedProvider (base trait)
//! ├── SecurityProvider
//! │   ├── CryptoProvider
//! │   └── HsmProvider
//! ├── MonitoringProvider
//! ├── StorageProvider
//! ├── NetworkProvider
//! ├── GeneticsProvider
//! ├── AdapterProvider
//! └── WorkflowProvider
//! ```

use beardog_errors::BearDogResult;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::SystemTime;

/// **CONSOLIDATED PROVIDER TRAIT** - Foundation of all providers
///
/// This is the core trait that all providers in the `BearDog` ecosystem must implement.
/// It provides the fundamental interface for provider lifecycle, health monitoring,
/// capabilities discovery, and metrics collection.
#[async_trait::async_trait]
pub trait ConsolidatedProvider: Send + Sync + 'static {
    /// Error type for this provider
    type Error: std::error::Error + Send + Sync + 'static;

    /// Configuration type for this provider
    type Config: Send + Sync + Clone + Serialize + for<'de> Deserialize<'de>;

    /// Provider-specific data type
    type Data: Send + Sync + Clone;

    /// Get provider identification information
    fn provider_info(&self) -> ProviderInfo;

    /// Get provider version string
    fn provider_version(&self) -> &str;

    /// Get list of capabilities this provider supports
    fn capabilities(&self) -> Vec<ProviderCapability>;

    /// Initialize the provider with configuration
    async fn initialize(&mut self, config: Self::Config) -> Result<(), Self::Error>;

    /// Perform health check and return current status
    async fn health_check(&self) -> Result<ProviderHealth, Self::Error>;

    /// Collect and return current performance metrics
    async fn metrics(&self) -> Result<ProviderMetrics, Self::Error>;

    /// Gracefully shutdown the provider
    async fn shutdown(&mut self) -> Result<(), Self::Error>;

    /// Get provider configuration (if available)
    fn get_config(&self) -> Option<&Self::Config> {
        None
    }

    /// Validate provider configuration
    fn validate_config(config: &Self::Config) -> Result<(), Self::Error>;

    /// Check if provider is ready to serve requests
    async fn is_ready(&self) -> bool {
        true
    }
}

/// **SECURITY PROVIDER** - Unified security operations
pub trait SecurityProvider: ConsolidatedProvider {
    /// Encrypt data using the provider's security capabilities
    fn encrypt(&self, data: &[u8], key: &str) -> BearDogResult<Vec<u8>>;

    /// Decrypt data using the provider's security capabilities  
    fn decrypt(&self, encrypted_data: &[u8], key: &str) -> BearDogResult<Vec<u8>>;

    /// Generate a secure key
    fn generate_key(&self, algorithm: &str, key_size: usize) -> BearDogResult<String>;

    /// Validate security credentials
    fn validate_credentials(&self, credentials: &HashMap<String, String>) -> BearDogResult<bool>;
}

/// **HSM PROVIDER** - Hardware Security Module operations
pub trait HsmProvider: SecurityProvider {
    /// Generate a key in the HSM
    fn hsm_generate_key(&self, algorithm: &str, key_size: usize) -> BearDogResult<String>;

    /// Sign data using HSM
    fn hsm_sign(&self, data: &[u8], key_id: &str) -> BearDogResult<Vec<u8>>;

    /// Verify signature using HSM
    fn hsm_verify(&self, data: &[u8], signature: &[u8], key_id: &str) -> BearDogResult<bool>;

    /// Get HSM status
    fn hsm_status(&self) -> BearDogResult<HsmStatus>;
}

/// **MONITORING PROVIDER** - System monitoring and observability
pub trait MonitoringProvider: ConsolidatedProvider {
    /// Collect system metrics
    fn collect_metrics(&self) -> BearDogResult<SystemMetrics>;

    /// Send alert
    fn send_alert(&self, alert: &Alert) -> BearDogResult<()>;

    /// Get service health
    fn get_health(&self) -> BearDogResult<ServiceHealth>;

    /// Record event
    fn record_event(&self, event: &SystemEvent) -> BearDogResult<()>;
}

/// **CRYPTO PROVIDER** - Cryptographic operations
pub trait CryptoProvider: SecurityProvider {
    /// Hash data
    fn hash(&self, data: &[u8], algorithm: &str) -> BearDogResult<Vec<u8>>;

    /// Generate random bytes
    fn generate_random(&self, length: usize) -> BearDogResult<Vec<u8>>;

    /// Create digital signature
    fn sign(&self, data: &[u8], private_key: &str) -> BearDogResult<Vec<u8>>;

    /// Verify digital signature
    fn verify(&self, data: &[u8], signature: &[u8], public_key: &str) -> BearDogResult<bool>;
}

/// **STORAGE PROVIDER** - Data storage operations (replaces `DatabaseProvider`)
pub trait StorageProvider: ConsolidatedProvider {
    /// Store data
    fn store(&self, key: &str, data: &[u8]) -> BearDogResult<()>;

    /// Retrieve data
    fn retrieve(&self, key: &str) -> BearDogResult<Vec<u8>>;

    /// Delete data
    fn delete(&self, key: &str) -> BearDogResult<()>;

    /// List keys
    fn list_keys(&self, prefix: &str) -> BearDogResult<Vec<String>>;

    /// Execute query
    fn execute_query(&self, query: &str) -> BearDogResult<DatabaseResult>;
}

/// **NETWORK PROVIDER** - Network operations (replaces `CacheProvider`)
pub trait NetworkProvider: ConsolidatedProvider {
    /// Send network request
    fn send_request(&self, request: &HttpRequest) -> BearDogResult<HttpResponse>;

    /// Cache data
    fn cache_set(&self, key: &str, value: &[u8], ttl: Option<u64>) -> BearDogResult<()>;

    /// Retrieve cached data
    fn cache_get(&self, key: &str) -> BearDogResult<Option<Vec<u8>>>;

    /// Remove from cache
    fn cache_delete(&self, key: &str) -> BearDogResult<()>;

    /// Get network status
    fn network_status(&self) -> BearDogResult<NetworkStatus>;
}

/// **WORKFLOW PROVIDER** - Workflow orchestration
pub trait WorkflowProvider: ConsolidatedProvider {
    /// Execute workflow
    fn execute_workflow(&self, workflow: &WorkflowDefinition) -> BearDogResult<WorkflowResult>;

    /// Get workflow status
    fn get_workflow_status(&self, workflow_id: &str) -> BearDogResult<WorkflowStatus>;

    /// Cancel workflow
    fn cancel_workflow(&self, workflow_id: &str) -> BearDogResult<()>;

    /// List active workflows
    fn list_workflows(&self) -> BearDogResult<Vec<WorkflowInstance>>;
}

/// **ADAPTER PROVIDER** - Universal adapter operations
pub trait AdapterProvider: ConsolidatedProvider {
    /// Discover available adapters
    fn discover_adapters(&self) -> BearDogResult<Vec<AdapterInfo>>;

    /// Connect to adapter
    fn connect_adapter(&self, adapter_id: &str) -> BearDogResult<AdapterConnection>;

    /// Execute adapter operation
    fn execute_operation(&self, operation: &AdapterRequest) -> BearDogResult<AdapterResponse>;

    /// Get adapter capabilities
    fn get_capabilities(&self, adapter_id: &str) -> BearDogResult<AdapterCapabilities>;
}

/// **GENETICS PROVIDER** - Genetic algorithm operations
pub trait GeneticsProvider: ConsolidatedProvider {
    /// Initialize population
    fn initialize_population(&self, size: usize) -> BearDogResult<Population>;

    /// Execute evolution step
    fn evolve(&self, population: &Population) -> BearDogResult<Population>;

    /// Evaluate fitness
    fn evaluate_fitness(&self, individual: &Individual) -> BearDogResult<f64>;

    /// Get evolution statistics
    fn get_statistics(&self) -> BearDogResult<EvolutionProgress>;
}

