// Type alias for common zero-cost registry configuration
pub type StandardZeroCostRegistry = ZeroCostProviderRegistry<
    MockSecurityProvider,
    MockHsmProvider,
    MockMonitoringProvider,
>;

impl StandardZeroCostRegistry {
    /// Create a standard zero-cost provider registry with mock implementations
    pub fn standard() -> Self {
        Self::new(ZeroCostRegistryConfig::default())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_zero_cost_registry_creation() {
        let registry = StandardZeroCostRegistry::standard();
        let stats = registry.get_statistics().await;

        // Verify zero-cost creation
        assert_eq!(stats.total_providers, 0);
        assert_eq!(stats.security_providers, 0);
        assert_eq!(stats.hsm_providers, 0);
        assert_eq!(stats.monitoring_providers, 0);
    }

    #[tokio::test]
    async fn test_zero_cost_provider_registration() {
        let registry = StandardZeroCostRegistry::standard();

        // Register providers with zero-cost dispatch
        let security_provider = MockSecurityProvider::new("test-security".to_string());
        let hsm_provider = MockHsmProvider::new("test-hsm".to_string());
        let monitoring_provider = MockMonitoringProvider::new("test-monitoring".to_string());

        let info = ProviderInfo {
            provider_id: "test".to_string(),
            provider_type: "test".to_string(),
            version: "1.0.0".to_string(),
            capabilities: vec![],
            metadata: std::collections::HashMap::new(),
        };

        registry.register_security_provider("test-security".to_string(), security_provider, info.clone()).await.unwrap();
        registry.register_hsm_provider("test-hsm".to_string(), hsm_provider, info.clone()).await.unwrap();
        registry.register_monitoring_provider("test-monitoring".to_string(), monitoring_provider, info).await.unwrap();

        let stats = registry.get_statistics().await;
        assert_eq!(stats.total_providers, 3);
        assert_eq!(stats.security_providers, 1);
        assert_eq!(stats.hsm_providers, 1);
        assert_eq!(stats.monitoring_providers, 1);
    }

    #[tokio::test]
    async fn test_zero_cost_provider_retrieval() {
        let registry = StandardZeroCostRegistry::standard();

        // Register and retrieve with compile-time dispatch
        let security_provider = MockSecurityProvider::new("test-security".to_string());
        let info = ProviderInfo {
            provider_id: "test-security".to_string(),
            provider_type: "security".to_string(),
            version: "1.0.0".to_string(),
            capabilities: vec![],
            metadata: std::collections::HashMap::new(),
        };

        registry.register_security_provider("test-security".to_string(), security_provider, info).await.unwrap();

        let retrieved = registry.get_security_provider("test-security").await.unwrap();
        assert_eq!(retrieved.provider_id, "test-security");
    }

    #[tokio::test]
    async fn test_zero_cost_health_checks() {
        let registry = StandardZeroCostRegistry::standard();

        // Register providers and perform health checks
        let mut security_provider = MockSecurityProvider::new("test-security".to_string());
        security_provider.initialized = true;

        let info = ProviderInfo {
            provider_id: "test-security".to_string(),
            provider_type: "security".to_string(),
            version: "1.0.0".to_string(),
            capabilities: vec![],
            metadata: std::collections::HashMap::new(),
        };

        registry.register_security_provider("test-security".to_string(), security_provider, info).await.unwrap();

        let health_results = registry.health_check_all().await.unwrap();
        assert_eq!(health_results.len(), 1);
        assert!(health_results.contains_key("test-security"));
    }
}

//! # Canonical Rate Limiting Configuration
//!
//! This module provides the canonical rate limiting configuration used across the BearDog ecosystem.
//!
//! ## Usage
//!
//! ```rust
//! use beardog_types::canonical::rate_limiting::{RateLimitConfig, RateLimitAlgorithm};
//!
//! let config = RateLimitConfig {
//!     enabled: true,
//!     requests_per_second: 100.0,
//!     burst_capacity: 200,
//!     window: std::time::Duration::from_secs(60),
//!     algorithm: RateLimitAlgorithm::TokenBucket,
//! };
//! ```
//!
//! ## Domain-Specific Variants
//!
//! Some domains have specialized rate limiting needs:
//!
//! - **Monitoring**: `NotificationRateLimitConfig` - For notification rate limiting with per-minute and per-hour limits
//! - **Services/Endpoints**: `EndpointRateLimitConfig` - For endpoint-specific rate limiting with scoping (per-IP, per-user, etc.)
//!
//! These are kept separate because they have fundamentally different semantics from general request rate limiting.

// Re-export the canonical implementation from config::domains::network
pub use super::config::domains::network::{
    RateLimitConfig, RateLimitStrategy as RateLimitAlgorithm,
};

#[cfg(test)]
mod tests {
    use super::*;
    use crate::canonical::config::domains::network::RateLimitStrategy;
    use std::time::Duration;

    #[test]
    fn test_default_rate_limit_config() {
        let config = RateLimitConfig::default();
        assert!(config.enabled);
        assert_eq!(config.max_requests, 100);
        assert_eq!(config.window, Duration::from_secs(60));
        assert_eq!(config.burst_size, Some(200));
        assert_eq!(config.strategy, RateLimitStrategy::TokenBucket);
    }
}

// Biological Relationship Types - Ecosystem Symbiosis Patterns
//
// This module implements biological relationship patterns that enable rich
// inter-primal symbiosis based on natural ecosystem relationships like
// mutualism, commensalism, and facilitation.

// Note: BearDogError and BearDogResult available for future extensions
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::Duration;

/// Biological relationship types for ecosystem interactions
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum BiologicalRelationship {
    /// Mutualistic relationship where both parties benefit
    Mutualistic {
        mutual_benefits: Vec<MutualBenefit>,
        benefit_balance: f64, // How balanced the benefits are (-1.0 to 1.0)
        sustainability_score: f64,
        evolution_potential: EvolutionPotential,
    },

    /// Commensal relationship where one benefits, other is neutral
    Commensal {
        beneficiary: String,
        neutral_party: String,
        benefit_type: BenefitType,
        impact_assessment: ImpactAssessment,
    },

    /// Facilitative relationship that helps ecosystem growth
    Facilitative {
        facilitator: String,
        facilitated_parties: Vec<String>,
        facilitation_methods: Vec<FacilitationMethod>,
        ecosystem_impact: EcosystemImpact,
    },

    /// Protective relationship that shields from threats
    Protective {
        protector: String,
        protected_parties: Vec<String>,
        protection_methods: Vec<ProtectionMethod>,
        threat_mitigation: ThreatMitigation,
    },

    /// Competitive relationship with healthy competition
    Competitive {
        competitors: Vec<String>,
        competition_areas: Vec<CompetitionArea>,
        competition_rules: CompetitionRules,
        ecosystem_benefits: Vec<String>,
    },
}

