        std::env::var("DATABASE_URL")
            .or_else(|_| std::env::var("BEARDOG_DATABASE_URL"))
            .unwrap_or_else(|_| {
                format!(
                    "postgresql://{}:{}/beardog",
                    default_service_host(),
                    DEFAULT_POSTGRES_PORT
                )
            })
    }

