    #[test]
    fn test_benchmark_creation() {
        let benchmark = PerformanceBenchmark::new("Test", 1000);
        assert_eq!(benchmark.name, "Test");
        assert_eq!(benchmark.iterations, 1000);
        assert_eq!(benchmark.warmup_iterations, 100);
    }

