pub enum PerformanceGrade {
    /// Represents excellent variant
    Excellent, // > 1M ops/sec
    /// Represents good variant
    Good, // > 100K ops/sec
    /// Represents average variant
    Average, // > 10K ops/sec
    /// Represents poor variant
    Poor, // > 1K ops/sec
