            (self.compress_data(value)?, true)
        } else {
            (value.to_vec(), false)
        };

        let entry = L2CacheEntry {
            data,
            created_at: Instant::now(),
            compressed,
        };

        self.entries.insert(key.to_string(), entry);
        self.update_stats();
        Ok(())
    }

