    fn update_stats(&mut self) {
        self.stats.entries = self.entries.len();
        self.stats.memory_usage_mb = self
            .entries
            .values()
            .map(|entry| entry.data.len())
            .sum::<usize>()
            / (1024 * 1024);
    }
