        let mut stats = self
            .stats
            .lock()
            .map_err(|e| BearDogError::internal(format!("Failed to lock memory stats: {e}")))?;

        if stats.current_usage >= size {
            stats.current_usage -= size;
        } else {
            stats.current_usage = 0;
        }

        Ok(())
    }

