        queue.push("item1".to_string());
        queue.push("item2".to_string());

        assert_eq!(queue.pop(), Some("item1".to_string()));
        assert_eq!(queue.pop(), Some("item2".to_string()));
        assert_eq!(queue.pop(), None);
    }
}

