pub fn global_fixtures() -> &'static TestFixtures {
    GLOBAL_FIXTURES.get_or_init(|| TestFixtures::new())
}

#[macro_export]
macro_rules! test_fixtures {
    () => {
        $crate::common::fixtures::global_fixtures()
