        let results = tester.test_overflow_boundaries(&values).unwrap();

        assert_eq!(results[0], true);  // Small value is safe
        assert_eq!(results[1], true);  // Quarter max is safe
        assert_eq!(results[2], false); // Near max is unsafe
    }
