                context.add_metadata("iterations", serde_json::json!(100));

                let start_time = std::time::Instant::now();

                for i in 0..100 {
                    let keypair =
                        beardog_security::crypto_utils::BearDogCrypto::generate_ed25519_keypair()
                            .map_err(|e| {
                            beardog_errors::BearDogError::crypto({}",
                                i, e
                            ))
                        })?;

                    let test_data = format!("benchmark_message_{}", i);
                    let signature = beardog_security::crypto_utils::BearDogCrypto::sign_ed25519(
                        &keypair.secret.to_bytes(),
                        test_data.as_bytes(),
                    )
                    .map_err(|e| {
                        beardog_errors::BearDogError::crypto({}",
                            i, e
                        ))
                    })?;

                    let is_valid =
                        beardog_security::crypto_utils::BearDogCrypto::verify_ed25519_signature(
                            &keypair.verifying_key.to_bytes(),
                            test_data.as_bytes(),
                            &signature,
                        )
                        .map_err(|e| {
                            beardog_errors::BearDogError::crypto({}",
                                i, e
                            ))
                        })?;

                    if !is_valid {
                        return Err(beardog_errors::BearDogError::authentication(&format!(
                            "Signature verification failed at iteration {}",
                            i
                        )));
                    }
                }

                let elapsed = start_time.elapsed();
                let ops_per_second = 100.0 / elapsed.as_secs_f64();

                context.add_metadata("benchmark_duration", serde_json::json!(elapsed.as_millis()));
                context.add_metadata("operations_per_second", serde_json::json!(ops_per_second));

                let perf_matcher = PerformanceMatcher::new()
                    .max_duration(Duration::from_secs(20))
                    .max_memory_mb(50.0);

                let perf_result = perf_matcher.matches(
                    &context,
                    &serde_json::json!({
                        "benchmar"k: "crypto_operations",
                        "iterations": 100
                    }),
                );

                assert_success({:.2} ops/sec",
                    ops_per_second
                );
                Ok(())
            },
        )
        ;

    harness.cleanup()?;
    result
}

