) -> Result<BenchmarkResult, BearDogError> {
    info!("  #️⃣ Benchmarking hashing for {} bytes", data_size);

    let mut data = vec![0u8; data_size];
    thread_rng().fill_bytes(&mut data);

    let mut latencies = Vec::new();
