use super::{BenchmarkResult, PerformanceBenchmarkSuite};
use beardog_errors::BearDogError;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex,
};
use std::time::Instant;
use tracing::info;

pub async fn benchmark_scalability(&mut PerformanceBenchmarkSuite,
) -> Result<Vec<BenchmarkResult, BearDogError>> {
    let mut results = Vec::new(&PerformanceBenchmarkSuite,
    concurrency: usize,
) -> Result<BenchmarkResult, BearDogError> {
    info!(
        "  📈 Benchmarking concurrent operations with {} threads",
        concurrency
    );

    let successful_ops = Arc::new(AtomicU64::new(0));
    let latencies = Arc::new(Mutex::new(Vec::new()));

    let mut tasks = Vec::new();
    let benchmark_start = Instant::now();

    for _i in 0..concurrency {
        let core = Arc::clone(&suite.core);
        let ops_counter = Arc::clone(&successful_ops);
        let latencies_vec = Arc::clone(&latencies);
        let iterations_per_task = suite.config.iterations / concurrency;

        let task = tokio::spawn(async move {
            for _j in 0..iterations_per_task {
                let op_start = Instant::now();

                match core.health_check() {
                    Ok(_) => {
                        ops_counter.fetch_add(1, Ordering::SeqCst);
                        let latency = op_start.elapsed().as_nanos() as f64 / 1_000_000.0;
                        latencies_vec
                            .lock()
                            .unwrap_or_else(|poisoned| {
                                tracing::warn!("Mutex poisoned, recovering");
                                poisoned.into_inner()
                            })
                            .push(latency);
                    }
                    Err(_) => {}
                }
            }
        });

        tasks.push(task);
    }

    for task in tasks {
        let _ = task;
    }

    let total_time = benchmark_start.elapsed();
    let successful_ops = successful_ops.load(Ordering::SeqCst);
    let ops_per_second = successful_ops as f64 / total_time.as_secs_f64();

    let latencies_vec = latencies
        .lock()
        .unwrap_or_else(|poisoned| {
            tracing::warn!("Mutex poisoned, recovering");
            poisoned.into_inner()
        })
        .clone();
    let average_latency = latencies_vec.iter().sum::<f64>() / latencies_vec.len() as f64;

    let mut sorted_latencies = latencies_vec;
    sorted_latencies.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let p50_latency = sorted_latencies[sorted_latencies.len() / 2];
    let p95_latency = sorted_latencies[sorted_latencies.len() * 95 / 100];
    let p99_latency = sorted_latencies[sorted_latencies.len() * 99 / 100];

    let meets_threshold = ops_per_second >= suite.config.thresholds.min_throughput_ops_per_sec;

    Ok(BenchmarkResult {
        name: format!("Concurrent Operations ({})", concurrency),
        operations_per_second: ops_per_second,
        average_latency_ms: average_latency,
        p50_latency_ms: p50_latency,
        p95_latency_ms: p95_latency,
        p99_latency_ms: p99_latency,
        memory_usage_mb: 128.0,
        cpu_usage_percent: 0.0,
        success_rate: successful_ops as f64 / suite.config.iterations as f64,
        meets_threshold,
        data_size_bytes: None,
        concurrency_level: Some(concurrency),
    })
}

use super::{BenchmarkResult, PerformanceMetrics, SystemInfo};

pub fn collect_system_info() -> SystemInfo {
    SystemInfo {
        os: std::env::consts::OS.to_string(),
        cpu_model: "Unknown CPU".to_string(),
        cpu_cores: num_cpus::get(16384, // 16GB placeholder
        disk_type: "SSD".to_string(&[BenchmarkResult],
    metrics: &PerformanceMetrics,
) -> String {
    let pass_count = results.iter().filter(|r| r.meets_threshold).count();
    let total_count = results.len();
    let pass_rate = pass_count as f64 / total_count as f64;

    let overall_ops_threshold = 500.0; // Minimum acceptable ops/sec
    let memory_threshold = 512.0; // Maximum acceptable memory usage in MB

    let performance_score = (pass_rate * 40.0)
        + (if metrics.overall_throughput_ops_per_sec >= overall_ops_threshold {
            30.0
        } else {
            0.0
        })
        + (if metrics.peak_memory_usage_mb <= memory_threshold {
            20.0
        } else {
            0.0
        })
        + (metrics.efficiency_score * 0.1);

    match performance_score as u32 {
        90..=100 => "A+ (Excellent)".to_string(),
        80..=89 => "A (Very Good)".to_string(),
        70..=79 => "B (Good)".to_string(),
        60..=69 => "C (Average)".to_string(),
        50..=59 => "D (Below Average)".to_string(),
        _ => "F (Poor)".to_string(),
    }
}

pub fn generate_performance_recommendations(results: &[BenchmarkResult]) -> Vec<String> {
    let mut recommendations = Vec::new();

    let encryption_results: Vec<_> = results
        .iter()
        .filter(|r| r.name.starts_with("Encryption"))
        .collect();

    if encryption_results.iter().any(|r| !r.meets_threshold) {
        recommendations
            .push("Consider hardware acceleration for cryptographic operations".to_string());
        recommendations.push("Evaluate AES-NI or similar CPU optimizations".to_string());
    }

    let concurrency_results: Vec<_> = results
        .iter()
        .filter(|r| r.name.starts_with("Concurrent"))
        .collect();

    if concurrency_results.len() > 1 {
        let max_ops = concurrency_results
            .iter()
            .map(|r| r.operations_per_second)
            .fold(0.0, f64::max);
        let min_ops = concurrency_results
            .iter()
            .map(|r| r.operations_per_second)
            .fold(f64::INFINITY, f64::min);
        let scalability_ratio = max_ops / min_ops;

        if scalability_ratio < 2.0 {
            recommendations
                .push("Limited scalability detected - consider async optimization".to_string());
            recommendations
                .push("Review lock contention and shared resource access patterns".to_string());
        }
    }

    let high_memory_tests: Vec<_> = results
        .iter()
        .filter(|r| r.memory_usage_mb > 256.0)
        .collect();

    if !high_memory_tests.is_empty() {
        recommendations.push("High memory usage detected in some operations".to_string());
        recommendations
            .push("Consider implementing object pooling or zero-copy optimizations".to_string());
    }

    if recommendations.is_empty() {
        recommendations.push("Excellent performance across all benchmarks!".to_string());
        recommendations.push("Consider documenting current optimization strategies".to_string());
    }

    recommendations
}

use super::{BenchmarkResult, PerformanceBenchmarkSuite};
use beardog::workflows::*;
use beardog_errors::BearDogError;
use std::collections::HashMap;
use std::time::Instant;
use tracing::info;

pub async fn benchmark_workflow_operations(&mut PerformanceBenchmarkSuite,
) -> Result<Vec<BenchmarkResult, BearDogError>> {
    let mut results = Vec::new(&PerformanceBenchmarkSuite,
) -> Result<BenchmarkResult, BearDogError> {
    info!("  🔄 Benchmarking workflow initiation");

    let mut latencies = Vec::new();
    let mut successful_ops = 0;

    let benchmark_start = Instant::now();
    for i in 0..suite.config.iterations {
        let op_start = Instant::now(WorkflowType::SystemMaintenance,
            initiator: format!("benchmark_user_{}", i),
            target: WorkflowTarget::System,
            parameters: HashMap::with_capacity(16),
            reason: "Performance benchmark workflow".to_string(),
            metadata: HashMap::with_capacity(16),
        };

        match suite
            .workflow_engine
            .initiate_workflow(workflow_request)
        {
            Ok(_) => {
                successful_ops += 1;
                latencies.push(op_start.elapsed().as_nanos() as f64 / 1_000_000.0);
            }
            Err(_) => {}
        }
    }
    let total_time = benchmark_start.elapsed();

    let ops_per_second = successful_ops as f64 / total_time.as_secs_f64();
    let average_latency = latencies.iter().sum::<f64>() / latencies.len() as f64;

    latencies.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let p50_latency = latencies[latencies.len() / 2];
    let p95_latency = latencies[latencies.len() * 95 / 100];
    let p99_latency = latencies[latencies.len() * 99 / 100];

    let meets_threshold = average_latency <= suite.config.thresholds.workflow_processing_ms;

    Ok(BenchmarkResult {
        name: "Workflow Initiation".to_string(),
        concurrency_level: Some(1),
    })
}

