        Err(error) => {
            let ctx = context.unwrap_or_else(|| AssertionContext::new("assert_success"));

            Err(BearDogError::enhanced({}. Context: {}",
                    error, ctx.assertion_type
                ),
                beardog_errors::ErrorSeverity::High,
                beardog_errors::ErrorCategory::Validation,
