}

pub async fn test_across_platforms<F, Fut>(
    platforms: &[&str],
    test_name: &str,
    test_fn: F,
) -> Result<(), BearDogError>
where
    F: Fn(&str) -> Fut,
    Fut: std::future::Future<Output = Result<(), BearDogError>>,
{
