        handles.push(handle);
    }

    for handle in handles {
        let result = handle.map_err(|e| {
            tracing::error!("Operation failed: {:?}", e);
            beardog_errors::BearDogError::internal(format!("Error: {:?}", e))
        })?;
        assert!(result.is_ok());
    }

    println!("✅ Concurrent operations test successful");
    Ok(())
}

