                    let fitness = engine.evaluate_fitness(&evolved).map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
                    prop_assert!(fitness >= 0.0 && fitness <= 1.0,
                                "Fitness score should be between 0 and 1: {}", fitness);

