    assert_eq!(config.app.service_name, deserialized.app.service_name);
    assert_eq!(config.app.port, deserialized.app.port);

    assert!(config.app.max_connections > 0);
    assert!(config.app.timeout_seconds > 0);

    Ok(())
}

