                .put(key, format!("value_{}", key).into_bytes())
                .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
        }

        for key in &warm_keys {
            let result = manager
                .get(key)
                .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
            assert!(result.is_some());
        }
    }
}

