async fn test_complete_workflow(harness: &mut HsmTestHarness) -> Result<(), BearDogError> {
    println!("  🔄 Testing complete HSM workflow");

    let system_status = harness.hsm_manager.get_system_status()?;
    assert!(system_status.operational, "System should be operational");

    let strongbox_key = harness
        .android_strongbox
        .generate_test_key("e2e_strongbox")
        ?;
    let software_key = harness
        .software_hsm
        .generate_test_key("e2e_software")
        ?;

    let test_data = "bend-to-end test data";
    let strongbox_sig = harness
        .android_strongbox
        .sign(&strongbox_key.key_id, test_data)
        ?;
    let software_sig = harness
        .software_hsm
        .sign(&software_key.key_id, test_data)
        ?;

    let strongbox_valid = harness
        .android_strongbox
        .verify(&strongbox_key.key_id, test_data, &strongbox_sig)
        ?;
    let software_valid = harness
        .software_hsm
        .verify(&software_key.key_id, test_data, &software_sig)
        ?;

    assert!(
        strongbox_valid && software_valid,
        "All signatures should be valid"
    );

    println!("    ✅ Complete workflow tests passed");
    Ok(())
}

