        assert_eq!(results[0], true);  // 1.0 is valid
        assert_eq!(results[1], false); // NaN is invalid
        assert_eq!(results[2], false); // Infinity is invalid
        assert_eq!(results[3], true);  // 0.0 is valid
    }

    #[test]
