        let mut handles = Vec::new();

        for i in 0..10 {
            let pool_clone = pool.clone();
            let handle = std::thread::spawn(move || {
                let mut local_buffers = Vec::new();

                for _ in 0..100 {
                    if let Ok(buffer) = pool_clone.get_buffer(4096) {
                        local_buffers.push(buffer);
                    }
