    fn test_error_conditions(
        &self,
    ) -> Pin<Box<dyn Future<Output = Result<TestResult, BearDogError>> + Send + '_>>;
}

pub trait QuantumResistanceValidator {
    fn validate_post_quantum_crypto(
        &self,
