fn count_rust_files(dir: &std::path::Path) -> Result<usize, Box<dyn std::error::Error>> {
    use std::fs;

    let mut count = 0;
    let entries = fs::read_dir(dir)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            count += count_rust_files(&path)?;
        } else if path.extension().map_or(false, |ext| ext == "rs") {
            count += 1;
        }
    }

    Ok(count)
}

